# owner: platform
"""Contact sheet for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

class ContactError(ValueError):
    """The students given cannot be turned into a contact sheet."""

def _cells(student: Student) -> Tuple[str, str, str]:
    if not student.email:
        raise ContactError(f"no email for {student.display_name}")
    return (student.display_name, student.section, student.email)

def _join_row(cells: Tuple[str, ...], widths: List[int]) -> str:
    padded = [text.ljust(width) for text, width in zip(cells, widths)]
    return "  ".join(padded).rstrip()

def contact_rows(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email, sorted by display name."""
    ordered = sorted(students, key=lambda item: item.display_name)
    if not ordered:
        raise ContactError("no students to list")
    cells = [_cells(student) for student in ordered]
    widths = [max(len(text) for text in column) for column in zip(*cells)]
    return [_join_row(row, widths) for row in cells]

