# owner: platform
import unittest

from rosterkit.contacts import ContactError, contact_rows
from rosterkit.models import Student

def make_student(last, first, section, email="x@example.invalid"):
    return Student(last + first, last, first, section, email)

class ContactRowTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows(
            [
                make_student("Thistle", "Bram", "A", "bram@example.invalid"),
                make_student("Quillon", "Ada", "B10", "ada@example.invalid")
            ]
        )
        self.assertEqual(
            rows,
            [
                "Quillon, Ada   B10  ada@example.invalid",
                "Thistle, Bram  A    bram@example.invalid"
            ]
        )

    def test_missing_email_names_student(self):
        students = [make_student("Thistle", "Bram", "A", None)]
        with self.assertRaises(ContactError) as caught:
            contact_rows(students)
        self.assertIn("Thistle, Bram", str(caught.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ContactError):
            contact_rows([make_student("Thistle", "Bram", "A", "")])

    def test_empty_list(self):
        with self.assertRaises(ContactError):
            contact_rows([])
